function(container, apiUrl, tables) {
  const logTableBody = container.querySelector('#log-table-body');
  const logDetailModal = container.querySelector('#log-detail-modal');
  const alertSettingsModal = container.querySelector('#alert-settings-modal');
  const errorIndicator = container.querySelector('#error-indicator');

  let autoUpdateInterval = null;
  let currentLogs = [];

  // ステータス表示用の関数
  function getStatusBadge(status) {
    const statusMap = {
      '成功': { color: '#28a745', text: '成功' },
      '失敗': { color: '#dc3545', text: '失敗' },
      '実行中': { color: '#ffc107', text: '実行中' },
      '警告': { color: '#fd7e14', text: '警告' }
    };
    const config = statusMap[status] || { color: '#6c757d', text: status };
    return `<span style="background: ${config.color}; color: white; padding: 2px 8px; border-radius: 12px; font-size: 12px;">${config.text}</span>`;
  }

  // ログ一覧の再描画
  function renderLogs(logs) {
    currentLogs = logs;
    logTableBody.innerHTML = logs.map(log => `
      <tr data-id="${log.ログID || log.id}">
        <td>${log.収集開始日時 ? new Date(log.収集開始日時).toLocaleString() : '-'}</td>
        <td>${log.データ種別 || '-'}</td>
        <td>${log.データソース || '-'}</td>
        <td>${log.店舗ID || '-'}</td>
        <td>${getStatusBadge(log.処理ステータス || '不明')}</td>
        <td>${log.収集件数 || 0}</td>
        <td>${log.エラー件数 || 0}</td>
        <td>${log.処理時間秒 || 0}秒</td>
        <td>${log.データ品質スコア || '-'}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${log.ログID || log.id}">詳細</button>
          ${(log.処理ステータス === '失敗' || log.エラー件数 > 0) ? 
            `<button class="action-btn retry-btn" data-id="${log.ログID || log.id}">再実行</button>` : ''}
        </td>
      </tr>
    `).join('');

    updateSummary(logs);
    updateErrorIndicator(logs);
  }

  // サマリー情報の更新
  function updateSummary(logs) {
    const total = logs.reduce((sum, log) => sum + (log.収集件数 || 0), 0);
    const success = logs.filter(log => log.処理ステータス === '成功').length;
    const error = logs.filter(log => log.処理ステータス === '失敗').length;
    const lastRun = logs.length > 0 ? 
      new Date(Math.max(...logs.map(log => new Date(log.収集開始日時 || 0)))).toLocaleString() : '-';

    container.querySelector('#summary-total').textContent = total;
    container.querySelector('#summary-success').textContent = success;
    container.querySelector('#summary-error').textContent = error;
    container.querySelector('#summary-last-run').textContent = lastRun;
  }

  // エラーインジケーターの更新
  function updateErrorIndicator(logs) {
    const errorLogs = logs.filter(log => log.処理ステータス === '失敗' || log.エラー件数 > 0);
    if (errorLogs.length > 0) {
      errorIndicator.classList.remove('hidden');
      container.querySelector('#error-details').textContent = 
        `${errorLogs.length}件のエラーが発生しています。最新エラー: ${errorLogs[0].エラーメッセージ || '詳細不明'}`;
    } else {
      errorIndicator.classList.add('hidden');
    }
  }

  // 初期データの読み込みと描画
  window.aivicApi.list(11).then(logs => {
    if (logs) {
      renderLogs(logs);
    }
  });

  // 検索・絞り込み
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const dataSource = container.querySelector('#select-data-source').value;
    const logLevel = container.querySelector('#select-log-level').value;
    const startDate = container.querySelector('#input-start-date').value;
    const endDate = container.querySelector('#input-end-date').value;

    // 日付範囲の検証
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert('開始日は終了日より前の日付を設定してください');
      return;
    }

    try {
      const logs = await window.aivicApi.list(11);
      if (!logs) return;

      let filteredLogs = logs.filter(log => {
        if (dataSource && log.データソース !== dataSource) return false;
        if (logLevel && !log.エラーメッセージ?.includes(logLevel)) return false;
        if (startDate && new Date(log.収集開始日時) < new Date(startDate)) return false;
        if (endDate && new Date(log.収集開始日時) > new Date(endDate)) return false;
        return true;
      });

      renderLogs(filteredLogs);
    } catch (error) {
      alert('検索処理でエラーが発生しました');
    }
  });

  // CSVエクスポート
  container.querySelector('#btn-export').addEventListener('click', async () => {
    try {
      const logs = await window.aivicApi.list(11);
      if (!logs) {
        alert('ログエクスポート処理が失敗しました');
        return;
      }

      const headers = ['収集日時', 'データ種別', 'データソース', '店舗ID', 'ステータス', '収集件数', 'エラー件数', '処理時間', '品質スコア', 'エラーメッセージ'];
      const csvContent = '\uFEFF' + [
        headers.join(','),
        ...logs.map(log => [
          log.収集開始日時 || '',
          log.データ種別 || '',
          log.データソース || '',
          log.店舗ID || '',
          log.処理ステータス || '',
          log.収集件数 || 0,
          log.エラー件数 || 0,
          log.処理時間秒 || 0,
          log.データ品質スコア || '',
          `"${(log.エラーメッセージ || '').replace(/"/g, '""')}"`
        ].join(','))
      ].join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `data_collection_logs_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    } catch (error) {
      alert('ログエクスポート処理が失敗しました');
    }
  });

  // 自動更新設定
  container.querySelector('#toggle-auto-update').addEventListener('change', (e) => {
    if (e.target.checked) {
      autoUpdateInterval = setInterval(async () => {
        const logs = await window.aivicApi.list(11);
        if (logs) renderLogs(logs);
      }, 30000); // 30秒間隔
    } else {
      if (autoUpdateInterval) {
        clearInterval(autoUpdateInterval);
        autoUpdateInterval = null;
      }
    }
  });

  // アラート通知設定
  container.querySelector('#btn-alert-settings').addEventListener('click', () => {
    alertSettingsModal.classList.remove('hidden');
  });

  container.querySelector('#btn-close-alert-modal').addEventListener('click', () => {
    alertSettingsModal.classList.add('hidden');
  });

  container.querySelector('#btn-cancel-alert-settings').addEventListener('click', () => {
    alertSettingsModal.classList.add('hidden');
  });

  container.querySelector('#btn-save-alert-settings').addEventListener('click', () => {
    const email = container.querySelector('#alert-email').value;
    const threshold = container.querySelector('#alert-threshold').value;
    const enabled = container.querySelector('#alert-enabled').checked;

    // 設定保存処理（実際の実装では設定テーブルに保存）
    alert('アラート通知設定を保存しました');
    alertSettingsModal.classList.add('hidden');
  });

  // イベントデリゲーション（詳細表示・再実行）
  container.addEventListener('click', async (e) => {
    // 詳細表示
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      const logId = detailBtn.dataset.id;
      const log = currentLogs.find(l => (l.ログID || l.id) === logId);
      if (log) {
        container.querySelector('#log-detail-content').innerHTML = `
          <div style="display: grid; gap: 15px;">
            <div><strong>ログID:</strong> ${log.ログID || log.id}</div>
            <div><strong>データ種別:</strong> ${log.データ種別 || '-'}</div>
            <div><strong>データソース:</strong> ${log.データソース || '-'}</div>
            <div><strong>店舗ID:</strong> ${log.店舗ID || '-'}</div>
            <div><strong>収集開始日時:</strong> ${log.収集開始日時 ? new Date(log.収集開始日時).toLocaleString() : '-'}</div>
            <div><strong>収集終了日時:</strong> ${log.収集終了日時 ? new Date(log.収集終了日時).toLocaleString() : '-'}</div>
            <div><strong>処理ステータス:</strong> ${log.処理ステータス || '-'}</div>
            <div><strong>対象期間:</strong> ${log.対象期間開始日 || '-'} ～ ${log.対象期間終了日 || '-'}</div>
            <div><strong>収集件数:</strong> ${log.収集件数 || 0}</div>
            <div><strong>エラー件数:</strong> ${log.エラー件数 || 0}</div>
            <div><strong>処理時間:</strong> ${log.処理時間秒 || 0}秒</div>
            <div><strong>データ品質スコア:</strong> ${log.データ品質スコア || '-'}</div>
            <div><strong>エラーメッセージ:</strong><br><pre style="background: var(--bg-main); padding: 10px; border-radius: 4px; white-space: pre-wrap; max-height: 200px; overflow-y: auto;">${log.エラーメッセージ || 'なし'}</pre></div>
            <div><strong>備考:</strong> ${log.備考 || '-'}</div>
          </div>
        `;
        logDetailModal.classList.remove('hidden');
      }
    }

    // 再実行
    const retryBtn = e.target.closest('.retry-btn');
    if (retryBtn) {
      if (!confirm('エラーログを再実行しますか？')) return;

      const logId = retryBtn.dataset.id;
      try {
        // 実際の実装では再実行APIを呼び出し
        // ここではステータス更新のシミュレーション
        await window.aivicApi.update(11, logId, { 
          処理ステータス: '実行中',
          更新日時: new Date().toISOString()
        });

        // 少し待ってから成功状態に更新
        setTimeout(async () => {
          await window.aivicApi.update(11, logId, { 
            処理ステータス: '成功',
            エラー件数: 0,
            エラーメッセージ: null,
            更新日時: new Date().toISOString()
          });

          const logs = await window.aivicApi.list(11);
          if (logs) renderLogs(logs);
        }, 2000);

        const logs = await window.aivicApi.list(11);
        if (logs) renderLogs(logs);
      } catch (error) {
        alert('エラーログの再実行が失敗しました');
      }
    }

    // モーダルクローズ
    if (e.target.closest('#btn-close-modal')) {
      logDetailModal.classList.add('hidden');
    }
  });

  // モーダル外クリックで閉じる
  logDetailModal.addEventListener('click', (e) => {
    if (e.target === logDetailModal) {
      logDetailModal.classList.add('hidden');
    }
  });

  alertSettingsModal.addEventListener('click', (e) => {
    if (e.target === alertSettingsModal) {
      alertSettingsModal.classList.add('hidden');
    }
  });

  // クリーンアップ
  return () => {
    if (autoUpdateInterval) {
      clearInterval(autoUpdateInterval);
    }
  };
}
